package com.resume.account.data

import jakarta.persistence.Column
import jakarta.persistence.Entity
import jakarta.persistence.Id
import jakarta.persistence.Table
import java.time.Instant

/**
 * Schema: docs/02-architecture-techlead/01-account-and-access/02-database-schema-design.md
 * (Flyway V1__account_core.sql). TEXT ids generated by domain services; no JPA
 * relationships (RLS keeps every access path predicate-scoped, never lazy-loaded).
 */
@Entity
@Table(name = "users")
class UserEntity(
    @Id var id: String = "",
    var email: String? = null,
    @Column(name = "email_verified") var emailVerified: Boolean = false,
    /** IdP email already verified on another account (BR-02): notice only, never a merge. */
    @Column(name = "email_conflict") var emailConflict: Boolean = false,
    @Column(name = "contact_email") var contactEmail: String? = null,
    @Column(name = "contact_verified_at") var contactVerifiedAt: Instant? = null,
    var name: String? = null,
    /** Avatar prefill target; feature 09 owns population rules. */
    @Column(name = "image_key") var imageKey: String? = null,
    @Column(name = "created_at") var createdAt: Instant = Instant.now(),
    @Column(name = "updated_at") var updatedAt: Instant = Instant.now(),
)

@Entity
@Table(name = "linked_accounts")
class LinkedAccountEntity(
    @Id var id: String = "",
    @Column(name = "user_id") var userId: String = "",
    @Column(name = "provider_id") var providerId: String = "",
    @Column(name = "provider_sub") var providerSub: String = "",
    @Column(name = "email_at_link") var emailAtLink: String? = null,
    @Column(name = "linked_at") var linkedAt: Instant = Instant.now(),
)

@Entity
@Table(name = "sessions")
class SessionEntity(
    @Id var sid: String = "",
    @Column(name = "user_id") var userId: String = "",
    @Column(name = "created_at") var createdAt: Instant = Instant.now(),
    @Column(name = "last_active_at") var lastActiveAt: Instant = Instant.now(),
    /** Step-up freshness source (BR-07); refreshed only by an SSO re-dance. */
    @Column(name = "auth_time") var authTime: Instant = Instant.now(),
    @Column(name = "idle_expires_at") var idleExpiresAt: Instant = Instant.now(),
    @Column(name = "absolute_expires_at") var absoluteExpiresAt: Instant = Instant.now(),
    @Column(name = "device_label") var deviceLabel: String? = null,
    /** Hashed coarse network class; raw IPs are never stored (NFR-12). */
    @Column(name = "ip_class") var ipClass: String? = null,
    @Column(name = "revoked_at") var revokedAt: Instant? = null,
)

@Entity
@Table(name = "audit_log")
class AuditEntryEntity(
    @Id var id: String = "",
    /** Actor (the account the event belongs to). */
    @Column(name = "user_id") var userId: String = "",
    /** Subject when different from the actor. */
    @Column(name = "subject_user_id") var subjectUserId: String? = null,
    var action: String = "",
    var target: String? = null,
    @Column(name = "at") var at: Instant = Instant.now(),
    @Column(name = "ip_class") var ipClass: String? = null,
)
